import { useEffect, useState } from 'react'

// Preferências de aparência do usuário: cor de destaque (--primary do site)
// e tema (light/dark/system). Fonte da verdade é o banco (coluna em `users`,
// migration 020); localStorage é apenas um CACHE local para aplicar sem flash
// antes de o perfil carregar, e a reatividade entre componentes é via
// CustomEvent. saveAppearancePrefs (services/appearance) grava no banco.

const ACCENT_KEY = 'encruzo:accent-color'
const THEME_KEY = 'encruzo:theme'
const ACCENT_EVENT = 'encruzo:accent-color-change'
export const DEFAULT_ACCENT = '#007aff' // azul iOS (mesmo default do variables.css)

export type ThemePref = 'light' | 'dark' | 'system'

export function getAccentColor(): string {
  if (typeof window === 'undefined') return DEFAULT_ACCENT
  return localStorage.getItem(ACCENT_KEY) || DEFAULT_ACCENT
}

export function getTheme(): ThemePref {
  if (typeof window === 'undefined') return 'system'
  return (localStorage.getItem(THEME_KEY) as ThemePref) || 'system'
}

// ---- Helpers de cor ----------------------------------------------------

function hexToRgb(hex: string): [number, number, number] {
  const h = hex.replace('#', '')
  const full = h.length === 3 ? h.split('').map(c => c + c).join('') : h
  const n = parseInt(full, 16)
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255]
}

function darken(hex: string, factor: number): string {
  const [r, g, b] = hexToRgb(hex)
  const d = (c: number) => Math.max(0, Math.round(c * (1 - factor)))
  return `#${[d(r), d(g), d(b)].map(c => c.toString(16).padStart(2, '0')).join('')}`
}

function rgba(hex: string, alpha: number): string {
  const [r, g, b] = hexToRgb(hex)
  return `rgba(${r}, ${g}, ${b}, ${alpha})`
}

/**
 * Sobrescreve as variáveis --primary* (e o anel de foco) em :root para a cor
 * dada, propagando para todo o site. null volta ao tema base.
 */
export function applyAccentColor(color: string | null) {
  if (typeof document === 'undefined') return
  const root = document.documentElement.style
  const vars = [
    '--primary',
    '--primary-hover',
    '--primary-active',
    '--primary-light',
    '--primary-lighter',
    '--ring-color',
  ]
  if (!color) {
    vars.forEach(v => root.removeProperty(v))
    return
  }
  root.setProperty('--primary', color)
  root.setProperty('--primary-hover', darken(color, 0.12))
  root.setProperty('--primary-active', darken(color, 0.24))
  root.setProperty('--primary-light', rgba(color, 0.1))
  root.setProperty('--primary-lighter', rgba(color, 0.05))
  root.setProperty('--ring-color', rgba(color, 0.4))
}

/** Aplica o tema (light/dark/system) como atributo data-theme em <html>. */
export function applyTheme(theme: ThemePref) {
  if (typeof document === 'undefined') return
  const resolved =
    theme === 'system'
      ? window.matchMedia('(prefers-color-scheme: dark)').matches
        ? 'dark'
        : 'light'
      : theme
  document.documentElement.setAttribute('data-theme', resolved)
}

// Listener único do SO: quando o tema salvo é 'system', re-resolve em tempo
// real ao usuário trocar o esquema do sistema operacional.
let mediaListenerBound = false
function bindSystemThemeListener() {
  if (mediaListenerBound || typeof window === 'undefined') return
  mediaListenerBound = true
  const mq = window.matchMedia('(prefers-color-scheme: dark)')
  mq.addEventListener('change', () => {
    if (getTheme() === 'system') applyTheme('system')
  })
}

// ---- Setters (cache local + aplicação + evento) ------------------------

export function setAccentColor(color: string) {
  localStorage.setItem(ACCENT_KEY, color)
  applyAccentColor(color)
  window.dispatchEvent(new CustomEvent(ACCENT_EVENT, { detail: color }))
}

export function setTheme(theme: ThemePref) {
  localStorage.setItem(THEME_KEY, theme)
  applyTheme(theme)
}

/** Aplica cor + tema salvos no cache no boot do app. Chamar uma vez na raiz. */
export function initAppearance() {
  applyAccentColor(getAccentColor())
  applyTheme(getTheme())
  bindSystemThemeListener()
}

/**
 * Sincroniza cache/aplicação a partir do perfil carregado do banco.
 * Chamar quando o usuário logado muda. Valores nulos caem no default.
 */
export function syncAppearanceFromUser(user: {
  accent_color?: string | null
  theme?: ThemePref | null
} | null) {
  if (!user) return
  const accent = user.accent_color || DEFAULT_ACCENT
  const theme = user.theme || 'system'
  localStorage.setItem(ACCENT_KEY, accent)
  localStorage.setItem(THEME_KEY, theme)
  applyAccentColor(accent)
  applyTheme(theme)
  window.dispatchEvent(new CustomEvent(ACCENT_EVENT, { detail: accent }))
}

/** Lê a cor de destaque de forma reativa. */
export function useAccentColor(): string {
  const [color, setColor] = useState<string>(getAccentColor)

  useEffect(() => {
    const onChange = (e: Event) => {
      const detail = (e as CustomEvent<string>).detail
      setColor(detail || getAccentColor())
    }
    const onStorage = (e: StorageEvent) => {
      if (e.key === ACCENT_KEY) {
        const next = e.newValue || DEFAULT_ACCENT
        setColor(next)
        applyAccentColor(next)
      }
    }
    window.addEventListener(ACCENT_EVENT, onChange)
    window.addEventListener('storage', onStorage)
    return () => {
      window.removeEventListener(ACCENT_EVENT, onChange)
      window.removeEventListener('storage', onStorage)
    }
  }, [])

  return color
}
