// Papel de plataforma do usuário logado (null = usuário comum de tenant).
export async function fetchPlatformRole(userId: string): Promise<PlatformRole | null> {
  const { data, error } = await supabase
    .from('platform')
    .select('role')
    .eq('user_id', userId)
    .maybeSingle()

  if (error) {
    console.error('Erro ao buscar papel de plataforma:', error)
    return null
  }
  return (data?.role as PlatformRole) ?? null
}

// Lista todas as contas (tenants) para o switcher. Só membros de plataforma
// recebem linhas (a RPC valida is_platform_member internamente).
export async function listAllTenants(): Promise<TenantSummary[]> {
  const { data, error } = await supabase.rpc('list_all_tenants')
  if (error) {
    console.error('Erro ao listar contas:', error)
    return []
  }
  return (data as TenantSummary[]) ?? []
}

// Registra que um membro de plataforma abriu a conta de um tenant (auditoria).
export async function logPlatformAccess(
  tenantId: string,
  action: string = 'open_account'
): Promise<void> {
  const { error } = await supabase.rpc('log_platform_access', {
    p_tenant_id: tenantId,
    p_action: action,
  })
  if (error) {
    // Não bloqueia a navegação do staff, apenas registra a falha.
    console.error('Erro ao registrar acesso de plataforma:', error)
  }
}

