export interface UpsertPlanInput {
  id?: string | null
  name: string
  slug: string
  price_cents: number
  currency: string
  interval: 'month' | 'year'
  limits: PlanLimits
  active: boolean
  sort_order: number
  trial_days: number
}

// Cria/atualiza um plano. Só admin (a RPC valida).
export async function upsertPlan(input: UpsertPlanInput): Promise<{ error: string | null }> {
  const { error } = await supabase.rpc('upsert_plan', {
    // p_id nulo => a função cria um plano novo. O gerador de tipos marca
    // p_id como obrigatório (o param SQL não tem DEFAULT), mas o corpo trata
    // NULL, então enviamos null explicitamente.
    p_id: (input.id ?? null) as unknown as string,
    p_name: input.name,
    p_slug: input.slug,
    p_price_cents: input.price_cents,
    p_currency: input.currency,
    p_interval: input.interval,
    p_limits: input.limits as unknown as Json,
    p_active: input.active,
    p_sort_order: input.sort_order,
    p_trial_days: input.trial_days,
  })
  return { error: error?.message ?? null }
}

// Vincula/troca o plano de um tenant. Só admin.
// status: 'active' (padrão) ou 'trialing' (período de teste).
export async function setTenantPlan(
  tenantId: string,
  planId: string,
  periodEnd: string | null = null,
  status: 'active' | 'trialing' = 'active'
): Promise<{ error: string | null }> {
  const { error } = await supabase.rpc('set_tenant_plan', {
    p_tenant_id: tenantId,
    p_plan_id: planId,
    p_period_end: periodEnd ?? undefined,
    p_status: status,
  })
  return { error: error?.message ?? null }
}

