// ---- Criação de conta (tenant) ---------------------------------------------

export interface CreateAccountInput {
  tenantName: string
  tenantSlug?: string
  ownerName: string
  ownerEmail: string
  planId?: string | null
}

export interface CreateAccountResult {
  tenant: { id: string; name: string; slug: string; created_at: string }
  user: { id: string; email: string; name: string }
  tempPassword: string
}

/**
 * Cria uma nova conta (tenant) completa via Edge Function.
 * Apenas admins de plataforma podem usar.
 */
export async function createAccount(input: CreateAccountInput): Promise<CreateAccountResult> {
  const { data, error } = await supabase.functions.invoke('create-account', {
    body: input,
  })

  if (error) {
    let message = error.message
    try {
      const ctx = (error as { context?: Response }).context
      if (ctx && typeof ctx.json === 'function') {
        const payload = await ctx.json()
        if (payload?.error) message = payload.error
      }
    } catch {
      // mantém error.message
    }
    throw new Error(message)
  }

  return data as CreateAccountResult
}
