import { useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { Building2, ChevronDown, Home, ShieldCheck } from 'lucide-react'
import { useTenant } from '@/hooks/useTenant'
import { listAllTenants } from '@/services/platform'
import type { TenantSummary } from '@/types/database'
import './AccountSwitcher.css'

// Seletor de conta para membros de PLATAFORMA (backoffice/técnico).
// Não renderiza nada para usuários comuns de tenant.
export default function AccountSwitcher() {
  const {
    isPlatform,
    platformRole,
    selectedTenantId,
    isImpersonating,
    selectTenant,
    resetToHomeTenant,
  } = useTenant()

  const [open, setOpen] = useState(false)
  const [tenants, setTenants] = useState<TenantSummary[]>([])
  const [loading, setLoading] = useState(false)
  const navigate = useNavigate()

  // Carrega as contas ao abrir o menu (uma vez), a partir do evento — não de
  // um efeito — para não disparar renders em cascata.
  const toggleOpen = () => {
    const next = !open
    setOpen(next)
    if (next && tenants.length === 0 && !loading) {
      setLoading(true)
      listAllTenants()
        .then(setTenants)
        .finally(() => setLoading(false))
    }
  }

  if (!isPlatform) return null

  const activeName =
    tenants.find(t => t.id === selectedTenantId)?.name ??
    (isImpersonating ? 'Conta do cliente' : 'Selecionar conta')

  return (
    <div className="acct-switcher">
      <div className="acct-switcher-badge">
        <ShieldCheck size={13} strokeWidth={2} />
        <span>
          {platformRole === 'admin' ? 'Admin de plataforma' : 'Backoffice · somente leitura'}
        </span>
      </div>

      <button
        className={`acct-switcher-trigger ${isImpersonating ? 'acct-switcher-trigger--active' : ''}`}
        onClick={toggleOpen}
        aria-expanded={open}
      >
        <Building2 size={16} strokeWidth={1.75} />
        <span className="acct-switcher-current">{activeName}</span>
        <ChevronDown
          size={15}
          className={`acct-switcher-caret ${open ? 'acct-switcher-caret--open' : ''}`}
        />
      </button>

      {open && (
        <div className="acct-switcher-menu" role="listbox">
          {isImpersonating && (
            <button
              className="acct-switcher-item acct-switcher-item--home"
              onClick={() => {
                resetToHomeTenant()
                setOpen(false)
                navigate('/platform')
              }}
            >
              <Home size={14} strokeWidth={1.75} />
              <span>Voltar ao console</span>
            </button>
          )}

          {loading && <div className="acct-switcher-empty">Carregando contas…</div>}

          {!loading && tenants.length === 0 && (
            <div className="acct-switcher-empty">Nenhuma conta encontrada</div>
          )}

          {!loading &&
            tenants.map(t => (
              <button
                key={t.id}
                className={`acct-switcher-item ${t.id === selectedTenantId ? 'acct-switcher-item--selected' : ''}`}
                onClick={() => {
                  selectTenant(t.id)
                  setOpen(false)
                }}
                role="option"
                aria-selected={t.id === selectedTenantId}
              >
                <span className="acct-switcher-item-name">{t.name}</span>
                <span className="acct-switcher-item-slug">{t.slug}</span>
              </button>
            ))}
        </div>
      )}
    </div>
  )
}
