import { createClient } from '@supabase/supabase-js'
import type { Database } from '@/types/supabase'

const supabaseUrl = import.meta.env.VITE_SUPABASE_URL as string
const supabaseAnonKey = import.meta.env.VITE_SUPABASE_ANON_KEY as string

if (!supabaseUrl || !supabaseAnonKey) {
  console.warn(
    'Supabase URL ou Anon Key não configurados. Configure as variáveis de ambiente VITE_SUPABASE_URL e VITE_SUPABASE_ANON_KEY.'
  )
}

export const supabase = createClient<Database>(supabaseUrl || '', supabaseAnonKey || '', {
  auth: {
    autoRefreshToken: true,
    persistSession: true,
    detectSessionInUrl: true,
  },
})

// Helper para obter tenant_id do usuário atual (cached)
let cachedTenantId: string | null = null

// Override de tenant ATIVO para membros de plataforma (backoffice/técnico).
// Quando setado, getTenantId() retorna este valor em vez do tenant natal,
// para que os services (clients/attendances/modules) sigam o switcher de conta.
let activeTenantOverride: string | null = null

export function setActiveTenantOverride(tenantId: string | null) {
  activeTenantOverride = tenantId
}

export async function getTenantId(): Promise<string> {
  if (activeTenantOverride) return activeTenantOverride
  if (cachedTenantId) return cachedTenantId

  const {
    data: { user },
  } = await supabase.auth.getUser()
  if (!user?.email) throw new Error('Usuário não autenticado')

  const { data } = await supabase.from('users').select('tenant_id').eq('email', user.email).single()

  if (!data?.tenant_id) throw new Error('Tenant não encontrado')

  cachedTenantId = data.tenant_id as string
  return cachedTenantId
}

// Limpar cache de tenant ao fazer logout
export function clearTenantCache() {
  cachedTenantId = null
  cachedUserId = null
  activeTenantOverride = null
}

// Helper para obter o id do usuário atual na tabela users (cached)
let cachedUserId: string | null = null

export async function getCurrentUserId(): Promise<string> {
  if (cachedUserId) return cachedUserId

  const {
    data: { user },
  } = await supabase.auth.getUser()
  if (!user?.email) throw new Error('Usuário não autenticado')

  const { data } = await supabase.from('users').select('id').eq('email', user.email).single()

  if (!data?.id) throw new Error('Usuário não encontrado')

  cachedUserId = data.id as string
  return cachedUserId
}

// Helper para verificar se usuário está autenticado
export async function isAuthenticated(): Promise<boolean> {
  const {
    data: { session },
  } = await supabase.auth.getSession()
  return !!session
}
