import { useId } from 'react'

interface EncruzoMarkProps {
  size?: number
  /**
   * 'onBrand'  → traços brancos + brasa âmbar (para fundo azul --primary)
   * 'standalone' → traços azuis + brasa âmbar (para fundo claro)
   */
  variant?: 'onBrand' | 'standalone'
  className?: string
}

/**
 * Símbolo da marca Encruzo: quatro caminhos convergindo para um ponto
 * central (a "brasa" âmbar) — a encruzilhada vista de cima.
 */
export function EncruzoMark({ size = 32, variant = 'onBrand', className }: EncruzoMarkProps) {
  const arm = variant === 'onBrand' ? '#ffffff' : undefined
  const diagOpacity = variant === 'onBrand' ? 0.55 : 0.3
  const diagColor = variant === 'onBrand' ? '#ffffff' : '#007aff'

  // IDs únicos por instância — evita colisão de gradientes quando o símbolo
  // é renderizado mais de uma vez na mesma página (login + sidebar).
  // useId() retorna algo como ":r0:" — os ':' são inválidos em url(#id),
  // o que quebra os gradientes (some tudo menos as diagonais). Sanitizamos.
  const raw = useId()
  const uid = `encruzo-${raw.replace(/[^a-zA-Z0-9-]/g, '')}`
  const p1 = `${uid}-p1`
  const p2 = `${uid}-p2`
  const core = `${uid}-core`

  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 100 100"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      role="img"
      aria-label="Encruzo"
      className={className}
    >
      <defs>
        <linearGradient id={p1} x1="0" y1="0" x2="100" y2="100" gradientUnits="userSpaceOnUse">
          <stop stopColor="#5ac8fa" />
          <stop offset="1" stopColor="#007aff" />
        </linearGradient>
        <linearGradient id={p2} x1="100" y1="0" x2="0" y2="100" gradientUnits="userSpaceOnUse">
          <stop stopColor="#007aff" />
          <stop offset="1" stopColor="#5856d6" />
        </linearGradient>
        <radialGradient id={core} cx="50%" cy="45%" r="55%">
          <stop stopColor="#ffcc00" />
          <stop offset="0.5" stopColor="#ff9500" />
          <stop offset="1" stopColor="#c93400" />
        </radialGradient>
      </defs>
      <path d="M50 14 L50 42" stroke={arm ?? `url(#${p1})`} strokeWidth="7" strokeLinecap="round" />
      <path d="M50 58 L50 86" stroke={arm ?? `url(#${p2})`} strokeWidth="7" strokeLinecap="round" />
      <path d="M14 50 L42 50" stroke={arm ?? `url(#${p2})`} strokeWidth="7" strokeLinecap="round" />
      <path d="M58 50 L86 50" stroke={arm ?? `url(#${p1})`} strokeWidth="7" strokeLinecap="round" />
      <path
        d="M26 26 L38 38"
        stroke={diagColor}
        strokeOpacity={diagOpacity}
        strokeWidth="4"
        strokeLinecap="round"
      />
      <path
        d="M74 74 L62 62"
        stroke={diagColor}
        strokeOpacity={diagOpacity}
        strokeWidth="4"
        strokeLinecap="round"
      />
      <path
        d="M74 26 L62 38"
        stroke={diagColor}
        strokeOpacity={diagOpacity}
        strokeWidth="4"
        strokeLinecap="round"
      />
      <path
        d="M26 74 L38 62"
        stroke={diagColor}
        strokeOpacity={diagOpacity}
        strokeWidth="4"
        strokeLinecap="round"
      />
      <circle cx="50" cy="50" r="13" fill={`url(#${core})`} />
    </svg>
  )
}
