import { useEffect, useRef, useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { Building2, Calendar, ChevronUp, LogOut, Palette, ShieldCheck, User } from 'lucide-react'
import { useAuthContext } from '@/hooks/AuthProvider'
import { useTenant } from '@/hooks/useTenant'
import { useAccentColor } from '@/hooks/useAccentColor'
import './UserMenu.css'

function getInitials(name?: string | null) {
  if (!name) return 'U'
  const parts = name.trim().split(/\s+/)
  if (parts.length === 1) return parts[0]?.charAt(0).toUpperCase() ?? 'U'
  const first = parts[0]?.charAt(0) ?? ''
  const last = parts[parts.length - 1]?.charAt(0) ?? ''
  return (first + last).toUpperCase() || 'U'
}

interface AvatarProps {
  name?: string | null
  avatarUrl?: string | null
  accent: string
  large?: boolean
}

// Foto do usuário quando existe; senão, iniciais sobre a cor de destaque
// escolhida em Aparência.
function Avatar({ name, avatarUrl, accent, large }: AvatarProps) {
  const cls = `user-menu-avatar${large ? ' user-menu-avatar--lg' : ''}`
  if (avatarUrl) {
    return <img className={cls} src={avatarUrl} alt="" />
  }
  return (
    <div className={cls} style={{ background: accent }}>
      {getInitials(name)}
    </div>
  )
}

interface UserMenuProps {
  /** Fecha a sidebar mobile ao navegar. */
  onNavigate?: () => void
  /** Sidebar colapsada: mostra só o avatar. */
  collapsed?: boolean
}

export default function UserMenu({ onNavigate, collapsed }: UserMenuProps) {
  const { user, signOut } = useAuthContext()
  const { isPlatform } = useTenant()
  const accent = useAccentColor()
  const navigate = useNavigate()
  const [open, setOpen] = useState(false)
  const rootRef = useRef<HTMLDivElement>(null)

  const isOwner = user?.role === 'owner'

  // Fecha ao clicar fora ou pressionar Escape.
  useEffect(() => {
    if (!open) return
    const onDown = (e: MouseEvent) => {
      if (rootRef.current && !rootRef.current.contains(e.target as Node)) {
        setOpen(false)
      }
    }
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') setOpen(false)
    }
    document.addEventListener('mousedown', onDown)
    document.addEventListener('keydown', onKey)
    return () => {
      document.removeEventListener('mousedown', onDown)
      document.removeEventListener('keydown', onKey)
    }
  }, [open])

  const go = (to: string) => {
    setOpen(false)
    onNavigate?.()
    navigate(to)
  }

  const name = user?.name || 'Usuário'
  const email = user?.email || ''

  return (
    <div className="user-menu" ref={rootRef}>
      {open && (
        <div className="user-menu-panel" role="menu">
          <div className="user-menu-head">
            <Avatar name={user?.name} avatarUrl={user?.avatar_url} accent={accent} large />
            <div className="user-menu-head-info">
              <span className="user-menu-head-name">{name}</span>
              {email && <span className="user-menu-head-email">{email}</span>}
            </div>
          </div>

          <div className="user-menu-sep" />

          <button className="user-menu-item" role="menuitem" onClick={() => go('/settings/perfil')}>
            <User size={16} strokeWidth={1.75} />
            <span>Meu Perfil</span>
          </button>

          {isOwner && (
            <button
              className="user-menu-item"
              role="menuitem"
              onClick={() => go('/settings/conta')}
            >
              <Building2 size={16} strokeWidth={1.75} />
              <span>Conta</span>
            </button>
          )}

          <button
            className="user-menu-item"
            role="menuitem"
            onClick={() => go('/settings/agendamento')}
          >
            <Calendar size={16} strokeWidth={1.75} />
            <span>Agendamento</span>
          </button>

          <button
            className="user-menu-item"
            role="menuitem"
            onClick={() => go('/settings/aparencia')}
          >
            <Palette size={16} strokeWidth={1.75} />
            <span>Aparência</span>
          </button>

          {isPlatform && (
            <button className="user-menu-item" role="menuitem" onClick={() => go('/platform')}>
              <ShieldCheck size={16} strokeWidth={1.75} />
              <span>Console da plataforma</span>
            </button>
          )}

          <div className="user-menu-sep" />

          <button
            className="user-menu-item user-menu-item--danger"
            role="menuitem"
            onClick={() => {
              setOpen(false)
              void signOut()
            }}
          >
            <LogOut size={16} strokeWidth={1.75} />
            <span>Sair</span>
          </button>
        </div>
      )}

      <button
        className={`user-menu-trigger ${open ? 'user-menu-trigger--open' : ''} ${collapsed ? 'user-menu-trigger--collapsed' : ''}`}
        onClick={() => setOpen(o => !o)}
        aria-haspopup="menu"
        aria-expanded={open}
        title={collapsed ? name : undefined}
      >
        <Avatar name={user?.name} avatarUrl={user?.avatar_url} accent={accent} />
        <div className="user-menu-trigger-info">
          <span className="user-menu-trigger-name">{name}</span>
          {email && <span className="user-menu-trigger-email">{email}</span>}
        </div>
        <ChevronUp
          size={16}
          strokeWidth={2}
          className={`user-menu-caret ${open ? 'user-menu-caret--open' : ''}`}
        />
      </button>
    </div>
  )
}
