import { useCallback, useEffect, useState } from 'react'
import { clearTenantCache, supabase } from '@/lib/supabase'
import type { Session, User as SupabaseUser } from '@supabase/supabase-js'
import type { PlatformRole, User } from '@/types/database'
import { fetchPlatformRole } from '@/services/platform'

interface AuthState {
  session: Session | null
  supabaseUser: SupabaseUser | null
  user: User | null
  platformRole: PlatformRole | null
  loading: boolean
  error: string | null
}

interface UseAuthReturn extends AuthState {
  signIn: (email: string, password: string) => Promise<{ error: string | null }>
  signUp: (
    email: string,
    password: string,
    name: string,
    tenantName: string
  ) => Promise<{ error: string | null }>
  signOut: () => Promise<void>
  resetPassword: (email: string) => Promise<{ error: string | null }>
}

export function useAuth(): UseAuthReturn {
  const [state, setState] = useState<AuthState>({
    session: null,
    supabaseUser: null,
    user: null,
    platformRole: null,
    loading: true,
    error: null,
  })

  // Buscar dados do usuário no banco
  const fetchUser = useCallback(async (email: string) => {
    const { data, error } = await supabase.from('users').select('*').eq('email', email).single()

    if (error) {
      console.error('Erro ao buscar usuário:', error)
      return null
    }
    return data as User
  }, [])

  // Inicializar sessão
  useEffect(() => {
    const initSession = async () => {
      try {
        const {
          data: { session },
        } = await supabase.auth.getSession()

        if (session?.user?.email) {
          const user = await fetchUser(session.user.email)
          const platformRole = user ? await fetchPlatformRole(user.id) : null
          setState({
            session,
            supabaseUser: session.user,
            user,
            platformRole,
            loading: false,
            error: null,
          })
        } else {
          setState(prev => ({ ...prev, loading: false }))
        }
      } catch {
        setState(prev => ({ ...prev, loading: false, error: 'Erro ao inicializar sessão' }))
      }
    }

    initSession()

    // Listener para mudanças de auth
    const {
      data: { subscription },
    } = supabase.auth.onAuthStateChange(async (event, session) => {
      if (event === 'SIGNED_IN' && session?.user?.email) {
        const user = await fetchUser(session.user.email)
        const platformRole = user ? await fetchPlatformRole(user.id) : null
        setState({
          session,
          supabaseUser: session.user,
          user,
          platformRole,
          loading: false,
          error: null,
        })
      } else if (event === 'SIGNED_OUT') {
        clearTenantCache()
        setState({
          session: null,
          supabaseUser: null,
          user: null,
          platformRole: null,
          loading: false,
          error: null,
        })
      }
    })

    return () => subscription.unsubscribe()
  }, [fetchUser])

  // Sign In
  const signIn = useCallback(async (email: string, password: string) => {
    setState(prev => ({ ...prev, loading: true, error: null }))

    const { error } = await supabase.auth.signInWithPassword({
      email,
      password,
    })

    if (error) {
      setState(prev => ({ ...prev, loading: false, error: error.message }))
      return { error: error.message }
    }

    return { error: null }
  }, [])

  // Sign Up (cria conta + tenant)
  const signUp = useCallback(
    async (email: string, password: string, name: string, tenantName: string) => {
      setState(prev => ({ ...prev, loading: true, error: null }))

      // 1. Criar usuário no Supabase Auth
      const { data: authData, error: authError } = await supabase.auth.signUp({
        email,
        password,
      })

      if (authError) {
        setState(prev => ({ ...prev, loading: false, error: authError.message }))
        return { error: authError.message }
      }

      if (!authData.user) {
        setState(prev => ({ ...prev, loading: false, error: 'Erro ao criar usuário' }))
        return { error: 'Erro ao criar usuário' }
      }

      // 2. Criar tenant + usuário no banco via função
      const slug = tenantName
        .toLowerCase()
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .replace(/[^a-z0-9]+/g, '-')
        .replace(/^-|-$/g, '')

      const { error: provisionError } = await supabase.rpc('provision_tenant', {
        p_tenant_name: tenantName,
        p_tenant_slug: slug,
        p_user_email: email,
        p_user_name: name,
      })

      if (provisionError) {
        // Tentar deletar o usuário auth criado
        console.error('Erro ao provisionar tenant:', provisionError)
        setState(prev => ({ ...prev, loading: false, error: provisionError.message }))
        return { error: provisionError.message }
      }

      setState(prev => ({ ...prev, loading: false }))
      return { error: null }
    },
    []
  )

  // Sign Out
  const signOut = useCallback(async () => {
    setState(prev => ({ ...prev, loading: true }))
    await supabase.auth.signOut()
    clearTenantCache()
    setState({
      session: null,
      supabaseUser: null,
      user: null,
      platformRole: null,
      loading: false,
      error: null,
    })
  }, [])

  // Reset Password
  const resetPassword = useCallback(async (email: string) => {
    const { error } = await supabase.auth.resetPasswordForEmail(email, {
      redirectTo: `${window.location.origin}/reset-password`,
    })

    if (error) {
      return { error: error.message }
    }
    return { error: null }
  }, [])

  return {
    ...state,
    signIn,
    signUp,
    signOut,
    resetPassword,
  }
}
