import { createContext, type ReactNode, useCallback, useContext, useEffect, useState } from 'react'
import { useQueryClient } from '@tanstack/react-query'
import { setActiveTenantOverride, supabase } from '@/lib/supabase'
import type { PlatformRole, Tenant, TherapyModule } from '@/types/database'
import { logPlatformAccess } from '@/services/platform'

interface TenantContextValue {
  tenant: Tenant | null
  modules: TherapyModule[]
  loading: boolean
  error: string | null
  refetchModules: () => Promise<void>
  // Contexto de plataforma (backoffice/técnico)
  isPlatform: boolean
  platformRole: PlatformRole | null
  homeTenantId: string | null
  selectedTenantId: string | null
  // true quando um membro de plataforma abriu a conta de um cliente
  // (está "dentro" do app do tenant, não no console).
  isImpersonating: boolean
  // Troca a conta ativa (só faz efeito para membros de plataforma).
  selectTenant: (tenantId: string) => void
  // Volta o staff/admin para a própria conta natal.
  resetToHomeTenant: () => void
}

const TenantContext = createContext<TenantContextValue | null>(null)

// Persistência da conta em impersonação: sobrevive a refresh/navegação e
// evita que a guarda de rota chute o operador de volta ao console.
const IMPERSONATE_KEY = 'encruzo.platform.impersonatedTenantId'

interface TenantProviderProps {
  // Tenant natal do usuário (users.tenant_id).
  tenantId: string | null
  // Papel de plataforma, quando houver.
  platformRole?: PlatformRole | null
  children: ReactNode
}

export function TenantProvider({ tenantId, platformRole = null, children }: TenantProviderProps) {
  const queryClient = useQueryClient()
  const [tenant, setTenant] = useState<Tenant | null>(null)
  const [modules, setModules] = useState<TherapyModule[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  const isPlatform = platformRole !== null

  // Conta que um membro de plataforma escolheu operar. null = está no console.
  // Inicializa do sessionStorage para sobreviver a refresh.
  const [impersonatedTenantId, setImpersonatedTenantId] = useState<string | null>(() => {
    if (typeof window === 'undefined') return null
    return window.sessionStorage.getItem(IMPERSONATE_KEY)
  })

  const isImpersonating = isPlatform && impersonatedTenantId !== null

  // Conta ativa (para dados): a conta em impersonação, ou a natal.
  const selectedTenantId = impersonatedTenantId ?? tenantId
  const activeTenantId = selectedTenantId

  // Mantém o override do supabase (usado por getTenantId nos services) em sincronia
  // com a conta ativa quando o usuário é membro de plataforma. Usuário comum
  // nunca seta override — segue o tenant natal via cache.
  useEffect(() => {
    if (isPlatform) {
      setActiveTenantOverride(activeTenantId)
    } else {
      setActiveTenantOverride(null)
    }
  }, [isPlatform, activeTenantId])

  const fetchTenantData = async (id: string) => {
    setLoading(true)
    setError(null)

    try {
      // Buscar tenant
      const { data: tenantData, error: tenantError } = await supabase
        .from('tenants')
        .select('*')
        .eq('id', id)
        .single()

      if (tenantError) throw tenantError
      setTenant(tenantData as Tenant)

      // Buscar módulos ativos
      const { data: modulesData, error: modulesError } = await supabase
        .from('therapy_modules')
        .select('*')
        .eq('tenant_id', id)
        .eq('active', true)
        .order('display_order')

      if (modulesError) throw modulesError
      setModules((modulesData as TherapyModule[]) || [])
    } catch (err) {
      console.error('Erro ao buscar dados do tenant:', err)
      setError('Erro ao carregar dados')
    } finally {
      setLoading(false)
    }
  }

  const refetchModules = async () => {
    if (!activeTenantId) return

    const { data, error: err } = await supabase
      .from('therapy_modules')
      .select('*')
      .eq('tenant_id', activeTenantId)
      .eq('active', true)
      .order('display_order')

    if (!err && data) {
      setModules(data as TherapyModule[])
    }
  }

  const resetTenantData = () => {
    setTenant(null)
    setModules([])
    setLoading(false)
  }

  useEffect(() => {
    if (activeTenantId) {
      fetchTenantData(activeTenantId)
    } else {
      resetTenantData()
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [activeTenantId])

  // Abre a conta de um cliente (impersonação read-only p/ staff). Só membro
  // de plataforma. Persiste em sessionStorage e seta o override ANTES de
  // qualquer navegação, para a guarda de rota já ver o novo estado.
  const selectTenant = useCallback(
    (id: string) => {
      if (!isPlatform || id === impersonatedTenantId) return
      window.sessionStorage.setItem(IMPERSONATE_KEY, id)
      setActiveTenantOverride(id)
      setImpersonatedTenantId(id)
      // Recarrega todas as telas no novo contexto de conta.
      void queryClient.invalidateQueries()
      // Auditoria: registra que a conta foi aberta pelo membro de plataforma.
      void logPlatformAccess(id, 'open_account')
    },
    [isPlatform, impersonatedTenantId, queryClient]
  )

  // Sai da conta do cliente e volta ao console (limpa a impersonação).
  const resetToHomeTenant = useCallback(() => {
    window.sessionStorage.removeItem(IMPERSONATE_KEY)
    setActiveTenantOverride(isPlatform ? null : tenantId)
    setImpersonatedTenantId(null)
    void queryClient.invalidateQueries()
  }, [isPlatform, tenantId, queryClient])

  return (
    <TenantContext.Provider
      value={{
        tenant,
        modules,
        loading,
        error,
        refetchModules,
        isPlatform,
        platformRole,
        homeTenantId: tenantId,
        selectedTenantId,
        isImpersonating,
        selectTenant,
        resetToHomeTenant,
      }}
    >
      {children}
    </TenantContext.Provider>
  )
}

// eslint-disable-next-line react-refresh/only-export-components
export function useTenant(): TenantContextValue {
  const context = useContext(TenantContext)
  if (!context) {
    throw new Error('useTenant must be used within a TenantProvider')
  }
  return context
}
