import { useEffect, useState } from 'react'
import { NavLink, useLocation } from 'react-router-dom'
import {
  Calendar,
  ChevronLeft,
  ChevronRight,
  LayoutDashboard,
  Menu,
  Puzzle,
  Users,
  X,
} from 'lucide-react'
import { EncruzoMark } from '../ui/EncruzoMark'
import AccountSwitcher from './AccountSwitcher'
import UserMenu from './UserMenu'
import './Sidebar.css'

const navItems = [
  { to: '/', icon: LayoutDashboard, label: 'Dashboard' },
  { to: '/clients', icon: Users, label: 'Clientes' },
  { to: '/attendances', icon: Calendar, label: 'Atendimentos' },
  { to: '/modules', icon: Puzzle, label: 'Módulos' },
]

const COLLAPSE_KEY = 'encruzo:sidebar-collapsed'

export default function Sidebar() {
  const location = useLocation()
  const [mobileOpen, setMobileOpen] = useState(false)
  const [collapsed, setCollapsed] = useState(
    () => localStorage.getItem(COLLAPSE_KEY) === '1'
  )

  const closeMobile = () => setMobileOpen(false)

  // Reflete a largura atual da sidebar numa CSS var em :root, para o
  // AppLayout recuar o conteúdo sem prop drilling.
  useEffect(() => {
    document.documentElement.style.setProperty(
      '--sidebar-current',
      collapsed ? 'var(--sidebar-collapsed-width)' : 'var(--sidebar-width)'
    )
    localStorage.setItem(COLLAPSE_KEY, collapsed ? '1' : '0')
  }, [collapsed])

  return (
    <>
      {/* Mobile top bar: toggle + marca */}
      <div className="sidebar-mobile-bar">
        <button
          className="sidebar-mobile-toggle"
          onClick={() => setMobileOpen(true)}
          aria-label="Abrir menu"
        >
          <Menu size={22} />
        </button>
        <div className="sidebar-mobile-brand">
          <img src="/favicon.svg" alt="" width="24" height="24" aria-hidden="true" />
          <span>Encruzo</span>
        </div>
      </div>

      {/* Mobile overlay */}
      <div
        className={`sidebar-overlay ${mobileOpen ? 'sidebar-overlay--visible' : ''}`}
        onClick={closeMobile}
        aria-hidden="true"
      />

      {/* Sidebar */}
      <aside
        className={`sidebar ${mobileOpen ? 'sidebar--open' : ''} ${collapsed ? 'sidebar--collapsed' : ''}`}
      >
        {/* Brand */}
        <div className="sidebar-brand">
          <button
            className="sidebar-logo"
            onClick={() => setCollapsed(false)}
            aria-label="Expandir menu"
            title={collapsed ? 'Expandir menu' : undefined}
            disabled={!collapsed}
          >
            <EncruzoMark size={32} variant="standalone" />
          </button>
          <div className="sidebar-brand-text">
            <span className="sidebar-title">Encruzo</span>
            <span className="sidebar-subtitle">Atendimentos e evolução</span>
          </div>

          {/* Chevron: recolhe (visível só quando expandido) */}
          <button
            className="sidebar-collapse-toggle"
            onClick={() => setCollapsed(true)}
            aria-label="Recolher menu"
            title="Recolher menu"
          >
            <ChevronLeft size={18} strokeWidth={2.25} />
          </button>

          {/* Mobile close */}
          <button className="sidebar-close" onClick={closeMobile} aria-label="Fechar menu">
            <X size={20} />
          </button>
        </div>

        {/* Main navigation */}
        <nav className="sidebar-nav">
          <div className="sidebar-section">
            <span className="sidebar-section-title">Menu principal</span>
            <ul className="sidebar-menu">
              {navItems.map(item => {
                const Icon = item.icon
                const isActive =
                  item.to === '/'
                    ? location.pathname === '/'
                    : location.pathname.startsWith(item.to)

                return (
                  <li key={item.to}>
                    <NavLink
                      to={item.to}
                      className={`sidebar-link ${isActive ? 'sidebar-link--active' : ''}`}
                      onClick={closeMobile}
                      title={collapsed ? item.label : undefined}
                    >
                      <span className="sidebar-link-icon">
                        <Icon size={20} strokeWidth={isActive ? 2 : 1.5} />
                      </span>
                      <span className="sidebar-link-label">{item.label}</span>
                      {isActive && <ChevronRight size={16} className="sidebar-link-arrow" />}
                    </NavLink>
                  </li>
                )
              })}
            </ul>
          </div>
        </nav>

        {/* Footer with user */}
        <div className="sidebar-footer">
          <AccountSwitcher />
          <UserMenu onNavigate={closeMobile} collapsed={collapsed} />
        </div>
      </aside>
    </>
  )
}
